import { defineHandlers } from '@stagecraft/core';
import type { DB } from './seed';

const ONBOARDING_STEPS = 4;

// Keys are "METHOD /path/:param". Mutate ctx.db to persist writes for the session.
export const handlers = defineHandlers<DB>({
  'GET /api/me': ({ db, persona, reply }) => {
    const me = db.users.find((u) => u.id === persona.userId);
    return me ?? reply(401, { error: 'Not signed in' });
  },
  'GET /api/account': ({ db }) => db.account,

  // Payments, newest first.
  'GET /api/payments': ({ db }) => [...db.payments].sort((a, b) => b.date.localeCompare(a.date)),

  'POST /api/payments/:id/:verb': ({ db, params, persona, reply }) => {
    if (params.verb !== 'approve' && params.verb !== 'reject') return reply(404, { error: 'Not found' });
    const p = db.payments.find((x) => x.id === params.id);
    if (!p) return reply(404, { error: 'Payment not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can approve or reject payments.' });
    if (db.account.status === 'frozen' && params.verb === 'approve')
      return reply(423, { error: 'This account is frozen. Payments cannot be approved right now.' });
    if (p.status !== 'pending_approval') return reply(409, { error: 'This payment is no longer waiting for approval.' });
    p.status = params.verb === 'approve' ? 'approved' : 'rejected';
    return p;
  },

  'POST /api/onboarding/complete-step': ({ db, persona, reply }) => {
    const me = db.users.find((u) => u.id === persona.userId);
    if (!me) return reply(401, { error: 'Not signed in' });
    me.onboardingStep = Math.min(ONBOARDING_STEPS, me.onboardingStep + 1);
    return me;
  },

  // Agents live on a separate host (https://api.ledgerly.example, listed in apiOrigins).
  'GET /api/agents': ({ db }) => db.agents,
  'PATCH /api/agents/:id': ({ db, params, body, persona, reply }) => {
    const a = db.agents.find((x) => x.id === params.id);
    if (!a) return reply(404, { error: 'Agent not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can change agent controls.' });
    const next = (body as { status?: string } | undefined)?.status;
    if (next !== 'active' && next !== 'paused') return reply(400, { error: 'Status must be active or paused.' });
    a.status = next;
    return a;
  },
});

